/**
 * Typography: the processTypo pattern catalog (src/Typography.js), the pre/post
 * integration (TextRunPass over the AST, titles, alt texts) and its
 * configuration surface.
 *
 * The processTypo replay corpus is generated by tools/typo-probe.php
 * (reference TypographyModule::postLine, cs locale).
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { describe, it } from "node:test";
import { fileURLToPath } from "node:url";
import { Module } from "../src/Modules/Module.js";
import { TypographyModule } from "../src/Modules/TypographyModule.js";
import { Syntax } from "../src/Syntax.js";
import { Texy } from "../src/Texy.js";
import { processTypo } from "../src/Typography.js";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const probe = JSON.parse(readFileSync(join(root, "..", "texy-fixtures", "typo-probe.json"), "utf8"));

/**
 * @param {string} text
 * @param {Object} [options]
 */
function processText(text, options) {
  const texy = new Texy();
  texy.allowed[Syntax.Hyphenation] = false;
  return texy.process(text, options);
}

describe("processTypo matches the reference pattern catalog", () => {
  it(`replays the ${probe.length}-case probe corpus (cs locale)`, () => {
    const divergences = [];
    for (const c of probe) {
      const got = processTypo(c.input.replaceAll("\t", " ").replace(/ {2,}/g, " "), { locale: "cs" });
      if (got !== c.expected) {
        divergences.push([c.input, c.expected, got]);
      }
    }
    // the catalog matches the reference postLine byte-for-byte,
    // including the nbsp-between-number-and-word class ("10 °C")
    assert.deepStrictEqual(divergences, []);
  });
});

describe("nbsp class composition", () => {
  it("keeps % and letters as classes, extends the symbol blocks; the letter class covers all scripts", () => {
    // the reference's legacy Letter ranges stop at U+1EFF; \p{Letter}
    // deliberately covers all scripts (CJK words bind with nbsp)
    assert.strictEqual(processTypo("123 你好", { locale: "cs" }), "123\u00A0你好");
    // the symbol blocks stay ranges - the °C gap fix
    assert.strictEqual(processTypo("10 °C", { locale: "cs" }), "10\u00A0°C");
    // no faithful class for them: punctuation like , stays outside
    assert.strictEqual(processTypo("123 , x", { locale: "cs" }), "123 , x");
  });
});

describe("TypographyModule.postLine", () => {
  /** @type {import('../src/Texy.js').Texy} */
  const texy = { allowed: {} };
  const module = new TypographyModule(texy);

  it("shrinks tabs and multiple spaces before the substitutions", () => {
    assert.strictEqual(module.postLine("a\t\tb  c..."), "a b c\u2026");
  });

  it("keeps spaces verbatim with preserveSpaces", () => {
    assert.strictEqual(module.postLine("a\t\tb  c...", true), "a\t\tb  c\u2026");
  });

  it("applies the configured locale quotation marks", () => {
    assert.strictEqual(module.postLine('"x"'), "\u201Ex\u201C"); // cs
    module.locale = "en";
    assert.strictEqual(module.postLine('"x"'), "\u201Cx\u201D"); // en
  });

  it("defaults the syntax switch to allowed", () => {
    assert.strictEqual(texy.allowed[Syntax.Typography], true);
  });
});

describe("typography in the pipeline", () => {
  it("typographs display text (cs locale)", () => {
    assert.strictEqual(
      processText('Hello world... 123-456 "in quotes"'),
      "<p>Hello world\u2026 123\u2013456 \u201Ein quotes\u201C</p>\n",
    );
  });

  it("protects code phrases, typographs around them", () => {
    assert.strictEqual(processText("Use `10-20` and 30-40"), "<p>Use <code>10-20</code> and 30\u201340</p>\n");
  });

  it("typographs the alternative text of an image", () => {
    assert.strictEqual(
      processText("[* img.jpg .(Nadpis knihy...) *]"),
      '<figure><img src="img.jpg" alt="Nadpis knihy\u2026"></figure>\n',
    );
  });

  it("treats block HTML as a segment boundary, phrase markup as transparent", () => {
    // block tag splits the typographic unit (each side typographed
    // independently); verified against the reference
    assert.strictEqual(
      processText("one two...\n\n<p>block content...</p>"),
      "<p>one two\u2026</p>\n\n<p>block content\u2026</p>\n",
    );

    // quotes span across **bold**: the markup markers are transparent to
    // the patterns and the result is written back into the text runs
    assert.strictEqual(
      processText('He said "very **bold** stuff" ok'),
      "<p>He said \u201Every <strong>bold</strong> stuff\u201C ok</p>\n",
    );
  });

  it("marks the document typographed and is idempotent", () => {
    const texy = new Texy();
    const doc = texy.parse("a... b");
    texy.transform(doc); // typography is a Finalize pass
    assert.strictEqual(doc.meta.typographed, true);

    const again = texy.parse("x... y");
    texy.transform(again);
    assert.strictEqual(again.content.children[0].content.children[0].text, "x\u2026 y");

    const before = doc.content.children[0].content.children[0].text;
    texy.applyAstTypography(doc); // already typographed: no-op
    assert.strictEqual(doc.content.children[0].content.children[0].text, before);
  });

  it("is disabled via allowed[Syntax.Typography] = false", () => {
    const texy = new Texy();
    texy.allowed[Syntax.Typography] = false;
    assert.strictEqual(texy.process("Hello world..."), "<p>Hello world...</p>\n");

    const doc = texy.parse("x... y");
    texy.transform(doc); // the pass runs, but with no transformers
    assert.strictEqual(doc.meta.typographed, true);
    assert.strictEqual(doc.content.children[0].content.children[0].text, "x... y");
  });

  it("renderer postLine fallback: typography applied to titles of a non-typographed document", () => {
    const texy = new Texy();
    texy.allowed[Syntax.Typography] = false;
    const doc = texy.parse("[* img.jpg .(Nadpis knihy...) *]");
    texy.allowed[Syntax.Typography] = true;

    // a document without the typographed mark (e.g. hand-built AST) gets
    // the renderer's postLine typography for isolated strings (alt)
    delete doc.meta.typographed;
    const html = texy.renderHtml(doc);
    assert.ok(html.includes('alt="Nadpis knihy\u2026"'));
  });
});
